def gaussian_elimination(A):
    m, n = len(A), len(A[0])
    for i in range(m):
        max_row = i
        for j in range(i+1, m):
            if abs(A[j][i]) > abs(A[max_row][i]):
                max_row = j
        A[i], A[max_row] = A[max_row], A[i]
        pivot = A[i][i]
        for j in range(n):
            A[i][j] /= pivot
        for j in range(m):
            if j != i:
                factor = A[j][i]
                for k in range(n):
                    A[j][k] -= factor * A[i][k]

def matrix_multiplication(A, B):
    m, n, p = len(A), len(B), len(B[0])
    C = [[0] * p for _ in range(m)]
    for i in range(m):
        for j in range(p):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

def is_independent(A, b):
    augmented = [row + [b[i]] for i, row in enumerate(A)]
    gaussian_elimination(augmented)
    for i in range(len(augmented)):
        if abs(augmented[i][-1]) > 1e-9 and any(abs(augmented[i][j]) > 1e-9 for j in range(len(augmented[0])-1)):
            return False
    return True

def rank(A):
    m, n = len(A), len(A[0])
    A_copy = [row[:] for row in A]
    gaussian_elimination(A_copy)
    return sum(1 for row in A_copy if any(abs(x) > 1e-9 for x in row))

